// A copy's package descriptor names its author and copyright.
//
// For a Track 1 copy the `.kps` is generated by the projection (step 3.6),
// before generateStubs would write one, so the attribution generateStubs puts
// into LICENSE.md never reached `<Info>`: the Ewondo hand test shipped a
// package with no <Copyright> and no <Author>. The descriptor now takes both
// from the same holder block as LICENSE.md. The `.kmn`'s store(&COPYRIGHT)
// still carries the starting keyboard's line (a recorded ruling).

import { describe, it, expect, vi, beforeEach } from "vitest";
import { createVirtualFS } from "@keyboard-studio/contracts";
import { makeStartKeyboard } from "@keyboard-studio/contracts/fixtures";
import { parseKmn } from "@keyboard-studio/engine";
import { useWorkingCopyStore } from "../stores/workingCopyStore.ts";
import { serializeWorkingCopy } from "./serializeWorkingCopy.ts";
import type { VirtualFS } from "@keyboard-studio/contracts";

let capturedVfs: VirtualFS | null = null;
vi.mock("./services.ts", () => ({
  getToZip: vi.fn(async () => async (vfs: VirtualFS) => {
    capturedVfs = vfs;
    return new Uint8Array([9, 9, 9]);
  }),
  getPatternLibraryService: vi.fn(() => ({ getById: vi.fn(async () => undefined) })),
}));

const KMN = [
  "store(&VERSION) '10.0'",
  "store(&TARGETS) 'windows'",
  "store(&COPYRIGHT) '© SIL Cameroon'",
  "begin Unicode > use(main)",
  "",
  "group(main) using keys",
  "+ [K_A] > 'a'",
  "",
].join("\n");

function text(path: string): string {
  const entry = capturedVfs!.get(path);
  if (entry === undefined) throw new Error(`${path} is not in the bundle`);
  return entry.content as string;
}

describe("serializeWorkingCopy — a copy's descriptor carries author and copyright", () => {
  beforeEach(async () => {
    capturedVfs = null;
    useWorkingCopyStore.getState().reset();
    const { ir } = parseKmn(KMN, "test_kb");
    const vfs = createVirtualFS([{ path: "source/test_kb.kmn", content: KMN, isBinary: false }]);
    const base = makeStartKeyboard({
      id: "test_kb",
      path: "release/test/test_kb",
      script: "Latn",
      targets: ["windows"],
      displayName: "Test KB",
      version: "1.0",
      sourceUrl: "https://example.invalid/test_kb",
      languages: ["en"],
    });
    const store = useWorkingCopyStore.getState();
    store.instantiateFromStart(base, { vfs, ir });
    store.setStartLicenseText("Copyright (c) 2018-2024 SIL Cameroon\n\nThe MIT License (MIT)\n");
    store.setAttribution({ authorName: "Ana Author", authorEmail: "ana@example.invalid", copyrightHolder: "" });
    expect(await serializeWorkingCopy()).not.toBeNull();
  });

  it("names the author, with the email as a mailto link", () => {
    expect(text("source/test_kb.kps")).toContain('<Author URL="mailto:ana@example.invalid">Ana Author</Author>');
  });

  it("states the new holder first and the copied keyboard's holder as portions", () => {
    const copyright = /<Copyright URL="">([^<]*)<\/Copyright>/.exec(text("source/test_kb.kps"))?.[1];
    expect(copyright).toMatch(/^Copyright © Ana Author\. Portions .*SIL Cameroon$/);
  });

  it("leaves the .kmn's carried store(&COPYRIGHT) as the copied keyboard wrote it", () => {
    expect(text("source/test_kb.kmn")).toContain("store(&COPYRIGHT) '© SIL Cameroon'");
  });
});
